CREATE OR REPLACE VIEW SILVER.SALES_LAST_3_MONTHS (SALE_ID decimal(10, 0) COMMENT 'Unique identifier for each sales transaction.', DATE_ID date COMMENT 'Unique identifier for the date.', MATERIAL_ID string COMMENT 'References the material sold in the transaction.', PLANT_ID string COMMENT 'References the plant associated with the transaction.', INVENTORY_ID decimal(10, 0) COMMENT 'References the inventory record for the material at the plant.', QUANTITY_SOLD decimal(10, 0) COMMENT 'Quantity of the material sold.', REVENUE decimal(10, 0) COMMENT 'Total revenue generated by the transaction.', SALE_DATE_ID date COMMENT 'Date of the sale, references the date dimension.', LAST_UPDATED_1) AS
SELECT SALE_ID, DATE_ID, MATERIAL_ID, PLANT_ID, INVENTORY_ID, QUANTITY_SOLD, REVENUE, SALE_DATE_ID
FROM POS.Silver.SALES_FACT
WHERE SALE_DATE_ID >= add_months(current_date(), -3);

